// Site behaviour. The HTML (header, nav, footer, content) is generated by build.py;
// this file only adds interaction, so every page still reads fine without JavaScript.
import { initWidgets } from "./ui.js";
import { initFilters } from "./filters.js";

export const ROOT = new URL(document.documentElement.dataset.root || "./", location.href);

function initMenu() {
  const menu = document.getElementById("site-menu");
  const toggle = document.querySelector(".menu-toggle");
  if (!menu || !toggle) return;
  const close = menu.querySelector(".menu-close");
  let timer;
  const open = (on) => {
    clearTimeout(timer);
    if (on) { menu.hidden = false; requestAnimationFrame(() => { menu.classList.add("is-open"); (menu.querySelector(".menu__list a") || close).focus(); }); }
    else { menu.classList.remove("is-open"); timer = setTimeout(() => (menu.hidden = true), 260); toggle.focus(); }
    document.body.classList.toggle("menu-open", on);
    toggle.setAttribute("aria-expanded", String(on));
  };
  toggle.addEventListener("click", () => open(true));
  close.addEventListener("click", () => open(false));
  document.addEventListener("keydown", (e) => {
    if (menu.hidden || toggle.getAttribute("aria-expanded") !== "true") return;
    if (e.key === "Escape") { e.preventDefault(); open(false); return; }
    if (e.key !== "Tab") return;
    const f = [...menu.querySelectorAll("a,button")], first = f[0], last = f[f.length - 1];
    if (!menu.contains(document.activeElement)) { e.preventDefault(); (e.shiftKey ? last : first).focus(); return; }
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
  });
  matchMedia("(min-width: 1100px)").addEventListener("change", (m) => { if (m.matches && !menu.hidden) open(false); });
}

// Reveal on scroll. rootMargin may only use px or % (other units throw a SyntaxError).
export function observeReveals(root = document) {
  const els = [...root.querySelectorAll(".reveal:not(.is-in)")];
  if (!els.length) return;
  if (!("IntersectionObserver" in window) || matchMedia("(prefers-reduced-motion: reduce)").matches) {
    els.forEach((e) => e.classList.add("is-in")); return;
  }
  const io = new IntersectionObserver((entries) => {
    for (const en of entries) if (en.isIntersecting) { en.target.classList.add("is-in"); io.unobserve(en.target); }
  }, { rootMargin: "0px 0px -5% 0px", threshold: 0 });
  els.forEach((e) => io.observe(e));
  // Safety net: never leave content invisible (e.g. printing, odd browsers).
  setTimeout(() => els.forEach((e) => e.classList.add("is-in")), 2500);
}

function initHeader() {
  const h = document.querySelector(".site-header");
  if (!h) return;
  const on = () => h.classList.toggle("is-scrolled", scrollY > 8);
  addEventListener("scroll", on, { passive: true }); on();
}

function initExpandAll() {
  document.querySelectorAll("[data-expand-all]").forEach((b) => b.addEventListener("click", () => {
    const on = b.getAttribute("aria-pressed") !== "true";
    b.setAttribute("aria-pressed", String(on)); b.textContent = on ? "Collapse all" : "Expand all";
    document.querySelectorAll(".answers [data-toggle]").forEach((t) => {
      t.setAttribute("aria-expanded", String(on));
      const p = document.getElementById(t.getAttribute("aria-controls")); if (p) p.hidden = !on;
    });
  }));
}

// Open an accordion when the URL points at it (e.g. answers/#bible-changed).
function openFromHash() {
  const id = decodeURIComponent(location.hash.slice(1));
  if (!id) return;
  const el = document.getElementById(id);
  const t = el?.querySelector("[data-toggle]");
  if (t && t.getAttribute("aria-expanded") !== "true") t.click();
  el?.classList.add("is-in", "is-target");
}

initMenu(); initHeader(); initWidgets(document); initFilters(document); initExpandAll(); observeReveals(); openFromHash();
addEventListener("hashchange", openFromHash);

const page = document.documentElement.dataset.page;
if (page) import(`./pages/${page}.js`).then((m) => m.init?.()).catch((e) => console.warn("page script:", e));
